import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    order = sorted(range(n), key=lambda i: a[i])
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

    for p in range(0, n, 2):
        union(p, p + 1)
    for k in range(n // 2):
        union(order[k], order[n - 1 - k])
    comps = sum(1 for i in range(n) if find(i) == i)
    print(n // 2 - comps)

